Certainly! Below is a simple example of a **neural network class in pure JavaScript** (no libraries). This is a basic feedforward neural network with one hidden layer, using sigmoid activation and trained with stochastic gradient descent (SGD) and backpropagation.

**Features:**
- One hidden layer
- Sigmoid activation
- Mean squared error loss
- No external libraries

```javascript
class NeuralNetwork {
    constructor(inputNodes, hiddenNodes, outputNodes, learningRate = 0.1) {
        this.inputNodes = inputNodes;
        this.hiddenNodes = hiddenNodes;
        this.outputNodes = outputNodes;
        this.learningRate = learningRate;

        // Initialize weights with random values
        this.weights_ih = this.randomMatrix(this.hiddenNodes, this.inputNodes);
        this.weights_ho = this.randomMatrix(this.outputNodes, this.hiddenNodes);

        // Initialize biases
        this.bias_h = this.randomMatrix(this.hiddenNodes, 1);
        this.bias_o = this.randomMatrix(this.outputNodes, 1);
    }

    // Helper to create a matrix with random values
    randomMatrix(rows, cols) {
        let arr = [];
        for (let i = 0; i < rows; i++) {
            arr[i] = [];
            for (let j = 0; j < cols; j++) {
                arr[i][j] = Math.random() * 2 - 1; // Range [-1, 1]
            }
        }
        return arr;
    }

    // Matrix operations
    static dot(a, b) {
        let result = [];
        for (let i = 0; i < a.length; i++) {
            result[i] = [];
            for (let j = 0; j < b[0].length; j++) {
                let sum = 0;
                for (let k = 0; k < a[0].length; k++) {
                    sum += a[i][k] * b[k][j];
                }
                result[i][j] = sum;
            }
        }
        return result;
    }

    static add(a, b) {
        let result = [];
        for (let i = 0; i < a.length; i++) {
            result[i] = [];
            for (let j = 0; j < a[0].length; j++) {
                result[i][j] = a[i][j] + b[i][j];
            }
        }
        return result;
    }

    static map(matrix, func) {
        let result = [];
        for (let i = 0; i < matrix.length; i++) {
            result[i] = [];
            for (let j = 0; j < matrix[0].length; j++) {
                result[i][j] = func(matrix[i][j], i, j);
            }
        }
        return result;
    }

    static transpose(matrix) {
        let result = [];
        for (let i = 0; i < matrix[0].length; i++) {
            result[i] = [];
            for (let j = 0; j < matrix.length; j++) {
                result[i][j] = matrix[j][i];
            }
        }
        return result;
    }

    static subtract(a, b) {
        let result = [];
        for (let i = 0; i < a.length; i++) {
            result[i] = [];
            for (let j = 0; j < a[0].length; j++) {
                result[i][j] = a[i][j] - b[i][j];
            }
        }
        return result;
    }

    static multiply(a, b) {
        // Element-wise multiplication
        let result = [];
        for (let i = 0; i < a.length; i++) {
            result[i] = [];
            for (let j = 0; j < a[0].length; j++) {
                result[i][j] = a[i][j] * b[i][j];
            }
        }
        return result;
    }

    static scalarMultiply(matrix, scalar) {
        return NeuralNetwork.map(matrix, x => x * scalar);
    }

    // Activation function and its derivative
    static sigmoid(x) {
        return 1 / (1 + Math.exp(-x));
    }

    static dsigmoid(y) {
        // y = sigmoid(x)
        return y * (1 - y);
    }

    // Convert array to column matrix
    static arrayToMatrix(arr) {
        let matrix = [];
        for (let i = 0; i < arr.length; i++) {
            matrix[i] = [arr[i]];
        }
        return matrix;
    }

    // Convert column matrix to array
    static matrixToArray(matrix) {
        let arr = [];
        for (let i = 0; i < matrix.length; i++) {
            arr.push(matrix[i][0]);
        }
        return arr;
    }

    // Feedforward
    predict(inputArray) {
        // Generating the Hidden Outputs
        let inputs = NeuralNetwork.arrayToMatrix(inputArray);
        let hidden = NeuralNetwork.dot(this.weights_ih, inputs);
        hidden = NeuralNetwork.add(hidden, this.bias_h);
        hidden = NeuralNetwork.map(hidden, NeuralNetwork.sigmoid);

        // Generating the output's output!
        let output = NeuralNetwork.dot(this.weights_ho, hidden);
        output = NeuralNetwork.add(output, this.bias_o);
        output = NeuralNetwork.map(output, NeuralNetwork.sigmoid);

        // Sending back to the caller!
        return NeuralNetwork.matrixToArray(output);
    }

    // Train with one sample
    train(inputArray, targetArray) {
        // Feedforward
        let inputs = NeuralNetwork.arrayToMatrix(inputArray);
        let hidden = NeuralNetwork.dot(this.weights_ih, inputs);
        hidden = NeuralNetwork.add(hidden, this.bias_h);
        hidden = NeuralNetwork.map(hidden, NeuralNetwork.sigmoid);

        let outputs = NeuralNetwork.dot(this.weights_ho, hidden);
        outputs = NeuralNetwork.add(outputs, this.bias_o);
        outputs = NeuralNetwork.map(outputs, NeuralNetwork.sigmoid);

        // Convert target array to matrix
        let targets = NeuralNetwork.arrayToMatrix(targetArray);

        // Calculate the error
        // ERROR = TARGETS - OUTPUTS
        let output_errors = NeuralNetwork.subtract(targets, outputs);

        // Calculate gradient
        let gradients = NeuralNetwork.map(outputs, NeuralNetwork.dsigmoid);
        gradients = NeuralNetwork.multiply(gradients, output_errors);
        gradients = NeuralNetwork.scalarMultiply(gradients, this.learningRate);

        // Calculate deltas
        let hidden_T = NeuralNetwork.transpose(hidden);
        let weight_ho_deltas = NeuralNetwork.dot(gradients, hidden_T);

        // Adjust the weights by deltas
        this.weights_ho = NeuralNetwork.add(this.weights_ho, weight_ho_deltas);
        // Adjust the bias by its deltas (which is just the gradients)
        this.bias_o = NeuralNetwork.add(this.bias_o, gradients);

        // Calculate the hidden layer errors
        let who_t = NeuralNetwork.transpose(this.weights_ho);
        let hidden_errors = NeuralNetwork.dot(who_t, output_errors);

        // Calculate hidden gradient
        let hidden_gradient = NeuralNetwork.map(hidden, NeuralNetwork.dsigmoid);
        hidden_gradient = NeuralNetwork.multiply(hidden_gradient, hidden_errors);
        hidden_gradient = NeuralNetwork.scalarMultiply(hidden_gradient, this.learningRate);

        // Calculate input->hidden deltas
        let inputs_T = NeuralNetwork.transpose(inputs);
        let weight_ih_deltas = NeuralNetwork.dot(hidden_gradient, inputs_T);

        this.weights_ih = NeuralNetwork.add(this.weights_ih, weight_ih_deltas);
        this.bias_h = NeuralNetwork.add(this.bias_h, hidden_gradient);
    }
}

// Example usage: XOR problem
let nn = new NeuralNetwork(2, 2, 1, 0.5);

// Training data for XOR
let data = [
    {input: [0, 0], target: [0]},
    {input: [0, 1], target: [1]},
    {input: [1, 0], target: [1]},
    {input: [1, 1], target: [0]}
];

// Train the network
for (let i = 0; i < 10000; i++) {
    let d = data[Math.floor(Math.random() * data.length)];
    nn.train(d.input, d.target);
}

// Test
console.log('0 XOR 0:', nn.predict([0, 0])[0]);
console.log('0 XOR 1:', nn.predict([0, 1])[0]);
console.log('1 XOR 0:', nn.predict([1, 0])[0]);
console.log('1 XOR 1:', nn.predict([1, 1])[0]);
```

---

**How it works:**
- The `NeuralNetwork` class handles all matrix math, activation, and training.
- The example at the end trains the network to solve the XOR problem.
- After training, the network should output values close to 0 or 1 for the XOR inputs.

