      success(result) {
        const formData = new FormData();
        formData.append("file", result, result.name);
        // Upload formData...
      },
      error(err) {
        console.error(err.message);
      },
    });
  };

  return (
    <input
      type="file"
      accept="image/jpg, image/jpeg, image/png, image/svg+xml, image/gif, image/webp"
